# Link infrastructure by shared payment sources (SYNTHETIC records).
# The 2018 GRU indictment used this kind of link: one bitcoin mining
# operation paid for the leak site and the spearphishing servers.
payments = [  # (paid from, bought)
    ("wallet-A", "domain leak-site.example"),
    ("wallet-A", "VPS 203.0.113.10 (phishing kit)"),
    ("wallet-B", "VPS 198.51.100.7 (mail relay)"),
    ("wallet-B", "wallet-A"),            # B topped up A
    ("wallet-C", "domain unrelated-shop.example"),
]
parent = {}
def find(x):
    parent.setdefault(x, x)
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x
def union(a, b):
    parent[find(a)] = find(b)

for src, item in payments:
    union(src, item)
groups = {}
for x in list(parent):
    groups.setdefault(find(x), []).append(x)
for i, members in enumerate(groups.values(), 1):
    print(f"cluster {i}:", ", ".join(sorted(members)))

# Output:
# cluster 1: VPS 198.51.100.7 (mail relay), VPS 203.0.113.10 (phishing kit), domain leak-site.example, wallet-A, wallet-B
# cluster 2: domain unrelated-shop.example, wallet-C
